package org.example



fun main() {
   do {
       println("Seleccione una opción:")
       println("1. Salir")
       println("2. Entrar al sistema")
       println("3. Mostrar información")
       val opcion = readLine()?.toIntOrNull()
       when (opcion) {
           1 -> eventosPantalla(PantallaEvent.Salir)
           2 -> {
               println("Ingrese su usuario:")
               val usuario = readLine() ?: ""
               eventosPantalla(PantallaEvent.EntrarSistema(usuario))
           }
           3 -> {
               println("Ingrese el nivel de información:")
               val nivel = readLine()?.toIntOrNull() ?: 0
               eventosPantalla(PantallaEvent.Informacion(nivel))
           }
       }
   }while (opcion != 1)
}

fun eventosPantalla(evento: PantallaEvent) {
    when (evento) {
        is PantallaEvent.Salir -> println("Saliendo de la pantalla")
        is PantallaEvent.EntrarSistema -> println("Entrando al sistema con usuario: ${evento.usuario}")
        is PantallaEvent.Informacion -> println("Mostrando información de nivel: ${evento.nivel}")
    }
}